package android.view;import java.util.*;public class ViewGroup extends View implements ViewParent{public static class LayoutParams{public final Object token=new Object();}public final List<View>children=new ArrayList<>();public static int operation,failAt;public static boolean failAfter,persistent;static void op(){operation++;if(!failAfter&&(operation==failAt||(persistent&&failAt>0&&operation>=failAt)))throw new IllegalStateException("view operation");}static void done(){if(failAfter&&(operation==failAt||(persistent&&failAt>0&&operation>=failAt)))throw new IllegalStateException("view operation after effect");}public int getChildCount(){return children.size();}public View getChildAt(int i){return children.get(i);}public void removeView(View v){op();if(children.remove(v))v.parent=null;done();}public void removeViewAt(int i){removeView(children.get(i));}public void removeAllViews(){for(View v:new ArrayList<>(children))removeView(v);}public void addView(View v){addView(v,children.size(),v.getLayoutParams());}public void addView(View v,int i){addView(v,i,v.getLayoutParams());}public void addView(View v,int i,LayoutParams p){op();if(v.parent!=null)throw new IllegalStateException("already parented");children.add(i,v);v.parent=this;v.setLayoutParams(p);done();}@Override public <T extends View>T findViewById(int i){T v=super.findViewById(i);if(v!=null)return v;for(View child:children){v=child.findViewById(i);if(v!=null)return v;}return null;}}
